const root = process.cwd();
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupDir = join(root, `backup-before-v011-${timestamp}`);

function fail(message) {
  console.error(`CHYBA: ${message}`);
  process.exit(1);
}

if (!existsSync(join(root, 'package.json'))) fail('Spustite skript v koreni projektu vedla package.json.');
if (!existsSync(join(root, 'src'))) fail('V koreni projektu chyba priecinok src.');

console.log('1/6 Vytvaram zalohu aktualneho projektu...');
mkdirSync(backupDir, { recursive: true });
cpSync(join(root, 'src'), join(backupDir, 'src'), { recursive: true });
cpSync(join(root, 'package.json'), join(backupDir, 'package.json'));
if (existsSync(join(root, '.env'))) cpSync(join(root, '.env'), join(backupDir, '.env'));
if (existsSync(join(root, 'supabase'))) cpSync(join(root, 'supabase'), join(backupDir, 'supabase'), { recursive: true });

console.log('2/6 Nahradzam zdrojovy priecinok konzistentnym release 0.11.0...');
rmSync(join(root, 'src'), { recursive: true, force: true });

console.log('3/6 Zapisujem release a Supabase konfiguracne subory...');
for (const [relativePath, compressed] of Object.entries(payload)) {
  const destination = join(root, relativePath);
  mkdirSync(dirname(destination), { recursive: true });
  writeFileSync(destination, gunzipSync(Buffer.from(compressed, 'base64')));
}

console.log('4/6 Overujem prihlasenie, cloudovy rezim a databazovu schemu...');
const app = readFileSync(join(root, 'src/App.tsx'), 'utf8');
const auth = readFileSync(join(root, 'src/auth/AuthContext.tsx'), 'utf8');
const client = readFileSync(join(root, 'src/lib/supabase.ts'), 'utf8');
const storage = readFileSync(join(root, 'src/lib/storage.ts'), 'utf8');
const raci = readFileSync(join(root, 'src/views/Raci.tsx'), 'utf8');
const required = [
  ['Cloud configuration screen', 'CloudSetupScreen'],
  ['Supabase Auth', 'AuthScreen'],
  ['Pouzivatelia', "label:'Používatelia'"],
  ['CMDB', 'CMDB / Aktíva'],
  ['IAM', 'IAM / Prístupy'],
  ['Problem management', 'Problem management'],
  ['Change management', 'Change management'],
];
for (const [label, needle] of required) {
  if (!app.includes(needle)) fail(`Kontrola zlyhala: ${label}.`);
  console.log(`OK: ${label}`);
}
if (!auth.includes('PASSWORD_RECOVERY') || !auth.includes('finishPasswordRecovery')) fail('AuthContext nema obnovu hesla 0.11.');
if (!client.includes('VITE_SUPABASE_PUBLISHABLE_KEY') || !client.includes('VITE_APP_MODE')) fail('Supabase klient nema konfiguraciu 0.11.');
if (!storage.includes("CURRENT_VERSION = '0.11.0'")) fail('storage.ts nema verziu 0.11.0.');
if (!raci.includes('PROCESS_COLUMN_WIDTH = 330')) fail('Chyba RACI oprava 0.10B.');
if (!existsSync(join(root, 'supabase/setup_v011.sql'))) fail('Chyba setup_v011.sql.');
if (!existsSync(join(root, 'supabase/functions/invite-user/index.ts'))) fail('Chyba Edge Function invite-user.');
console.log('OK: prihlasenie a obnova hesla');
console.log('OK: publishable/anon key');
console.log('OK: cloud/auto/local rezim');
console.log('OK: RLS setup a Edge Function');
console.log('OK: RACI oprava');

console.log('5/6 Kontrolujem package.json...');
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
if (pkg.version !== '0.11.0') fail('package.json nema verziu 0.11.0.');
if (!pkg.dependencies?.['@supabase/supabase-js']) fail('V package.json chyba @supabase/supabase-js.');
console.log('OK: package 0.11.0');

